mapper.update:
UPDATE resumes
SET analyze_status = 'PENDING',
    analysis_message_id = #{messageId},
    analysis_idempotency_key_hash = #{idempotencyKeyHash},
    analysis_attempt_count = 0,
    analysis_deadline_at = NULL,
    updated_by = #{userId},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{resumeId}
  AND user_id = #{userId}
  AND is_deleted = FALSE
  AND analyze_status = #{expectedStatus}
  AND analysis_message_id IS NOT DISTINCT FROM #{expectedMessageId}

UPDATE resumes
SET analyze_status = 'COMPLETED',
    analysis_deadline_at = NULL,
    updated_by = #{userId},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{resumeId}
  AND user_id = #{userId}
  AND analysis_message_id = #{messageId}
  AND analysis_attempt_count = #{attemptCount}
  AND analyze_status = 'PROCESSING'
  AND is_deleted = FALSE

UPDATE resumes
SET analyze_status = 'PENDING',
    analysis_deadline_at = NULL,
    updated_by = #{userId},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{resumeId}
  AND user_id = #{userId}
  AND analysis_message_id = #{messageId}
  AND analysis_attempt_count = #{attemptCount}
  AND analyze_status = 'PROCESSING'
  AND is_deleted = FALSE

UPDATE resumes
SET analyze_status = 'FAILED',
    analysis_deadline_at = NULL,
    updated_by = #{userId},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{resumeId}
  AND user_id = #{userId}
  AND analysis_message_id = #{messageId}
  AND analysis_attempt_count = #{attemptCount}
  AND analyze_status = 'PROCESSING'
  AND is_deleted = FALSE

UPDATE resumes
SET analyze_status = 'FAILED',
    analysis_deadline_at = NULL,
    updated_by = #{userId},
    trace_id = #{traceId},
    updated_at = #{now}
WHERE id = #{resumeId}
  AND user_id = #{userId}
  AND analysis_message_id = #{messageId}
  AND COALESCE(analysis_attempt_count, 0) >= #{maxAttempts}
  AND is_deleted = FALSE
  AND (
      analyze_status = 'PENDING'
      OR (
          analyze_status = 'PROCESSING'
          AND (analysis_deadline_at IS NULL OR analysis_deadline_at <= #{now})
      )
  )
